import unittest
from datetime import date

from salesreport.records import Sale, sales_since


def sale(day: str) -> Sale:
    return Sale(day, "north", "widget", 1, 10.0)


class TestSalesSince(unittest.TestCase):
    def test_keeps_sales_on_or_after_date(self):
        sales = [sale("2024-01-31"), sale("2024-02-01"), sale("2024-02-02")]
        kept = sales_since(sales, date(2024, 2, 1))
        self.assertEqual([s.date for s in kept], ["2024-02-01", "2024-02-02"])

    def test_skips_rows_with_invalid_dates(self):
        sales = [sale("not-a-date"), sale("2024-02-01")]
        kept = sales_since(sales, date(2024, 1, 1))
        self.assertEqual([s.date for s in kept], ["2024-02-01"])


if __name__ == "__main__":
    unittest.main()

